import { Loader2Icon } from "lucide-react"

import { cn } from "../../lib/utils"

function Spinner({
  className,
  ...props
}) {
  return (
    <Loader2Icon
      role="status"
      aria-label="Loading"
      className={cn("size-24 animate-spin text-green-light", className)}
      {...props} />
  );
}

export { Spinner }
